function replaceFirst(values, oldValue, newValue) {
  const result = values.slice();
  const index = result.indexOf(oldValue);
  if (index !== -1) result.splice(index, 1, newValue);
  return result;
}
console.log(JSON.stringify(replaceFirst(["A", "B", "A"], "A", "X")));
const items = ["A", "B"];
console.log(JSON.stringify(items.splice(0, 1, "X")));
console.log(JSON.stringify(items));
